/**
 * Deterministic statistics core for the research workflows (plan §9, §9.3).
 *
 * Pure functions, no randomness except an explicitly SEEDED PRNG (bootstrap), so a
 * run is reproducible bit-for-bit. Distribution functions are implemented from the
 * standard algorithms (Lanczos log-gamma, regularised incomplete gamma/beta via
 * series + continued fractions, Acklam's normal quantile with one Halley step) and
 * are TESTED against scipy-computed reference values (src/research/scipy-vectors.json,
 * regenerated by scripts/gen-stats-vectors.py). Nothing here is a clinical claim.
 */

// ── special functions ────────────────────────────────────────────────────────

const LANCZOS = [0.99999999999980993, 676.5203681218851, -1259.1392167224028, 771.32342877765313, -176.61502916214059,
  12.507343278686905, -0.13857109526572012, 9.9843695780195716e-6, 1.5056327351493116e-7];

export function lgamma(x: number): number {
  if (x < 0.5) return Math.log(Math.PI / Math.abs(Math.sin(Math.PI * x))) - lgamma(1 - x);
  x -= 1;
  let a = LANCZOS[0];
  const t = x + 7.5;
  for (let i = 1; i < 9; i++) a += LANCZOS[i] / (x + i);
  return 0.5 * Math.log(2 * Math.PI) + (x + 0.5) * Math.log(t) - t + Math.log(a);
}

/** Regularised upper incomplete gamma Q(a, x). */
function gammaQ(a: number, x: number): number {
  if (x <= 0) return 1;
  if (x < a + 1) { // series for P
    let sum = 1 / a, term = sum;
    for (let n = 1; n < 1000; n++) { term *= x / (a + n); sum += term; if (Math.abs(term) < Math.abs(sum) * 1e-16) break; }
    return 1 - sum * Math.exp(-x + a * Math.log(x) - lgamma(a));
  }
  let b = x + 1 - a, c = 1 / 1e-300, d = 1 / b, h = d; // continued fraction (Lentz)
  for (let i = 1; i < 1000; i++) {
    const an = -i * (i - a); b += 2;
    d = an * d + b; if (Math.abs(d) < 1e-300) d = 1e-300;
    c = b + an / c; if (Math.abs(c) < 1e-300) c = 1e-300;
    d = 1 / d; const del = d * c; h *= del;
    if (Math.abs(del - 1) < 1e-16) break;
  }
  return Math.exp(-x + a * Math.log(x) - lgamma(a)) * h;
}

export function erfc(x: number): number { return x >= 0 ? gammaQ(0.5, x * x) : 2 - gammaQ(0.5, x * x); }
export function normCdf(x: number): number { return 0.5 * erfc(-x / Math.SQRT2); }

/** Standard normal quantile: Acklam's approximation + one Halley refinement (~1e-15). */
export function normQuantile(p: number): number {
  if (!(p > 0 && p < 1)) throw new RangeError('p must be in (0,1)');
  const a = [-3.969683028665376e1, 2.209460984245205e2, -2.759285104469687e2, 1.383577518672690e2, -3.066479806614716e1, 2.506628277459239];
  const b = [-5.447609879822406e1, 1.615858368580409e2, -1.556989798598866e2, 6.680131188771972e1, -1.328068155288572e1];
  const c = [-7.784894002430293e-3, -3.223964580411365e-1, -2.400758277161838, -2.549732539343734, 4.374664141464968, 2.938163982698783];
  const d = [7.784695709041462e-3, 3.224671290700398e-1, 2.445134137142996, 3.754408661907416];
  let x: number;
  if (p < 0.02425) { const q = Math.sqrt(-2 * Math.log(p)); x = (((((c[0] * q + c[1]) * q + c[2]) * q + c[3]) * q + c[4]) * q + c[5]) / ((((d[0] * q + d[1]) * q + d[2]) * q + d[3]) * q + 1); }
  else if (p > 1 - 0.02425) { const q = Math.sqrt(-2 * Math.log(1 - p)); x = -(((((c[0] * q + c[1]) * q + c[2]) * q + c[3]) * q + c[4]) * q + c[5]) / ((((d[0] * q + d[1]) * q + d[2]) * q + d[3]) * q + 1); }
  else { const q = p - 0.5, r = q * q; x = (((((a[0] * r + a[1]) * r + a[2]) * r + a[3]) * r + a[4]) * r + a[5]) * q / (((((b[0] * r + b[1]) * r + b[2]) * r + b[3]) * r + b[4]) * r + 1); }
  const e = normCdf(x) - p, u = e * Math.sqrt(2 * Math.PI) * Math.exp(x * x / 2);
  return x - u / (1 + x * u / 2);
}

function betacf(a: number, b: number, x: number): number {
  const qab = a + b, qap = a + 1, qam = a - 1;
  let c = 1, d = 1 - qab * x / qap; if (Math.abs(d) < 1e-300) d = 1e-300; d = 1 / d;
  let h = d;
  for (let m = 1; m < 1000; m++) {
    const m2 = 2 * m;
    let aa = m * (b - m) * x / ((qam + m2) * (a + m2));
    d = 1 + aa * d; if (Math.abs(d) < 1e-300) d = 1e-300; c = 1 + aa / c; if (Math.abs(c) < 1e-300) c = 1e-300; d = 1 / d; h *= d * c;
    aa = -(a + m) * (qab + m) * x / ((a + m2) * (qap + m2));
    d = 1 + aa * d; if (Math.abs(d) < 1e-300) d = 1e-300; c = 1 + aa / c; if (Math.abs(c) < 1e-300) c = 1e-300; d = 1 / d;
    const del = d * c; h *= del;
    if (Math.abs(del - 1) < 1e-16) break;
  }
  return h;
}

/** Regularised incomplete beta I_x(a,b). */
export function ibeta(x: number, a: number, b: number): number {
  if (x <= 0) return 0; if (x >= 1) return 1;
  const bt = Math.exp(lgamma(a + b) - lgamma(a) - lgamma(b) + a * Math.log(x) + b * Math.log(1 - x));
  return x < (a + 1) / (a + b + 2) ? bt * betacf(a, b, x) / a : 1 - bt * betacf(b, a, 1 - x) / b;
}

export function tCdf(t: number, df: number): number {
  const x = df / (df + t * t);
  const tail = 0.5 * ibeta(x, df / 2, 0.5);
  return t > 0 ? 1 - tail : tail;
}

export function tQuantile(p: number, df: number): number {
  if (!(p > 0 && p < 1)) throw new RangeError('p must be in (0,1)');
  if (p === 0.5) return 0;
  let lo = -1e3, hi = 1e3;
  for (let i = 0; i < 200; i++) { const mid = (lo + hi) / 2; if (tCdf(mid, df) < p) lo = mid; else hi = mid; }
  return (lo + hi) / 2;
}

// ── descriptive ──────────────────────────────────────────────────────────────

function finiteNums(xs: number[]): number[] {
  if (!Array.isArray(xs) || xs.some((x) => typeof x !== 'number' || !Number.isFinite(x))) throw new TypeError('values must be finite numbers');
  return xs;
}

/** Linear-interpolation percentile (numpy default, "type 7"). */
export function percentile(sorted: number[], q: number): number {
  const pos = (sorted.length - 1) * q, lo = Math.floor(pos), hi = Math.ceil(pos);
  return sorted[lo] + (sorted[hi] - sorted[lo]) * (pos - lo);
}

export interface Described { n: number; mean: number; sd: number | null; median: number; q1: number; q3: number; min: number; max: number }
export function describe(xs: number[]): Described {
  finiteNums(xs);
  if (!xs.length) throw new RangeError('no values');
  const n = xs.length, mean = xs.reduce((a, b) => a + b, 0) / n;
  const s = [...xs].sort((a, b) => a - b);
  const sd = n > 1 ? Math.sqrt(xs.reduce((a, b) => a + (b - mean) ** 2, 0) / (n - 1)) : null;
  return { n, mean, sd, median: percentile(s, 0.5), q1: percentile(s, 0.25), q3: percentile(s, 0.75), min: s[0], max: s[n - 1] };
}

// ── inference ────────────────────────────────────────────────────────────────

export interface WelchResult { status: 'ok' | 'insufficient_data' | 'zero_variance'; t?: number; df?: number; p?: number; diff?: number; ciLow?: number; ciHigh?: number; n1: number; n2: number; confidence: number }

export function welchT(a: number[], b: number[], confidence = 0.95): WelchResult {
  finiteNums(a); finiteNums(b);
  const base = { n1: a.length, n2: b.length, confidence };
  if (a.length < 2 || b.length < 2) return { status: 'insufficient_data', ...base };
  const da = describe(a), db = describe(b);
  const v1 = da.sd! ** 2 / a.length, v2 = db.sd! ** 2 / b.length;
  if (v1 + v2 === 0) return { status: 'zero_variance', diff: da.mean - db.mean, ...base };
  const se = Math.sqrt(v1 + v2), t = (da.mean - db.mean) / se;
  const df = (v1 + v2) ** 2 / (v1 ** 2 / (a.length - 1) + v2 ** 2 / (b.length - 1));
  const p = Math.min(1, 2 * (1 - tCdf(Math.abs(t), df)));
  const q = tQuantile(1 - (1 - confidence) / 2, df), diff = da.mean - db.mean;
  return { status: 'ok', t, df, p, diff, ciLow: diff - q * se, ciHigh: diff + q * se, ...base };
}

export function wilson(k: number, n: number, confidence = 0.95): { low: number; high: number; estimate: number } {
  if (!Number.isInteger(k) || !Number.isInteger(n) || n <= 0 || k < 0 || k > n) throw new RangeError('invalid counts');
  const z = normQuantile(1 - (1 - confidence) / 2), ph = k / n, z2 = z * z;
  const centre = (ph + z2 / (2 * n)) / (1 + z2 / n), half = z * Math.sqrt(ph * (1 - ph) / n + z2 / (4 * n * n)) / (1 + z2 / n);
  return { low: Math.max(0, centre - half), high: Math.min(1, centre + half), estimate: ph };
}

export interface RatioResult { status: 'ok' | 'undefined_zero_cell'; ratio?: number; low?: number; high?: number; note?: string }

/** Risk ratio, Katz log method. Zero cells are reported as undefined (no silent continuity correction). */
export function riskRatio(a: number, n1: number, c: number, n2: number, confidence = 0.95): RatioResult {
  for (const v of [a, n1, c, n2]) if (!Number.isInteger(v) || v < 0) throw new RangeError('counts must be non-negative integers');
  if (a > n1 || c > n2 || n1 === 0 || n2 === 0) throw new RangeError('events cannot exceed group size');
  if (a === 0 || c === 0) return { status: 'undefined_zero_cell', note: 'A cell is zero; the ratio and its interval are not estimable without an explicit correction.' };
  const rr = (a / n1) / (c / n2), se = Math.sqrt(1 / a - 1 / n1 + 1 / c - 1 / n2), z = normQuantile(1 - (1 - confidence) / 2);
  return { status: 'ok', ratio: rr, low: Math.exp(Math.log(rr) - z * se), high: Math.exp(Math.log(rr) + z * se) };
}

/** Incidence rate ratio, log method (conditional on observed counts). */
export function rateRatio(c1: number, t1: number, c2: number, t2: number, confidence = 0.95): RatioResult {
  if (![c1, c2].every((v) => Number.isInteger(v) && v >= 0) || ![t1, t2].every((v) => Number.isFinite(v) && v > 0)) throw new RangeError('invalid counts or person-time');
  if (c1 === 0 || c2 === 0) return { status: 'undefined_zero_cell', note: 'A case count is zero; the rate ratio is not estimable without an explicit method.' };
  const irr = (c1 / t1) / (c2 / t2), se = Math.sqrt(1 / c1 + 1 / c2), z = normQuantile(1 - (1 - confidence) / 2);
  return { status: 'ok', ratio: irr, low: Math.exp(Math.log(irr) - z * se), high: Math.exp(Math.log(irr) + z * se) };
}

/** Benjamini–Hochberg adjusted p-values (q-values), monotone, same order as input. */
export function benjaminiHochberg(p: number[]): number[] {
  finiteNums(p);
  if (p.some((x) => x < 0 || x > 1)) throw new RangeError('p-values must be in [0,1]');
  const m = p.length, idx = p.map((v, i) => [v, i] as const).sort((a, b) => a[0] - b[0]);
  const q = new Array<number>(m); let prev = 1;
  for (let r = m; r >= 1; r--) { const [v, i] = idx[r - 1]; prev = Math.min(prev, v * m / r); q[i] = prev; }
  return q;
}

// ── prediction evaluation ────────────────────────────────────────────────────

/** Seeded PRNG (mulberry32) so bootstraps are reproducible. */
export function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => { a = (a + 0x6D2B79F5) >>> 0; let t = a; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
}

function checkBinary(y: number[], s: number[]) {
  finiteNums(s);
  if (y.length !== s.length || !y.length) throw new RangeError('y and score must be equal, non-empty length');
  if (y.some((v) => v !== 0 && v !== 1)) throw new TypeError('labels must be 0/1');
}

/** AUC via the Mann–Whitney identity with mid-ranks for ties. Undefined when one class is absent. */
export function auc(y: number[], s: number[]): number | null {
  checkBinary(y, s);
  const pos = y.filter((v) => v === 1).length, neg = y.length - pos;
  if (!pos || !neg) return null;
  const order = s.map((v, i) => [v, i] as const).sort((a, b) => a[0] - b[0]);
  const ranks = new Array<number>(s.length);
  for (let i = 0; i < order.length;) {
    let j = i; while (j + 1 < order.length && order[j + 1][0] === order[i][0]) j++;
    const r = (i + j) / 2 + 1; for (let k = i; k <= j; k++) ranks[order[k][1]] = r; i = j + 1;
  }
  const sumPos = ranks.reduce((acc, r, i) => acc + (y[i] === 1 ? r : 0), 0);
  return (sumPos - pos * (pos + 1) / 2) / (pos * neg);
}

/** Stratified percentile bootstrap CI for AUC with a seeded PRNG. */
export function aucBootstrapCI(y: number[], s: number[], opts: { B?: number; seed?: number; confidence?: number } = {}): { low: number; high: number; B: number; seed: number } | null {
  checkBinary(y, s);
  const B = opts.B ?? 1000, seed = opts.seed ?? 12345, conf = opts.confidence ?? 0.95;
  const posIdx = y.map((v, i) => (v === 1 ? i : -1)).filter((i) => i >= 0), negIdx = y.map((v, i) => (v === 0 ? i : -1)).filter((i) => i >= 0);
  if (!posIdx.length || !negIdx.length) return null;
  const rnd = mulberry32(seed), vals: number[] = [];
  for (let b = 0; b < B; b++) {
    const idx: number[] = [];
    for (let i = 0; i < posIdx.length; i++) idx.push(posIdx[Math.floor(rnd() * posIdx.length)]);
    for (let i = 0; i < negIdx.length; i++) idx.push(negIdx[Math.floor(rnd() * negIdx.length)]);
    const a = auc(idx.map((i) => y[i]), idx.map((i) => s[i]));
    if (a !== null) vals.push(a);
  }
  vals.sort((a, b) => a - b);
  return { low: percentile(vals, (1 - conf) / 2), high: percentile(vals, 1 - (1 - conf) / 2), B, seed };
}

export function brier(y: number[], p: number[]): number {
  checkBinary(y, p);
  if (p.some((v) => v < 0 || v > 1)) throw new RangeError('probabilities must be in [0,1]');
  return y.reduce((a, v, i) => a + (p[i] - v) ** 2, 0) / y.length;
}

/** Equal-width reliability bins and expected calibration error. Small bins are reported, not hidden. */
export function calibration(y: number[], p: number[], bins = 10): { ece: number; bins: Array<{ lo: number; hi: number; n: number; meanPred: number | null; observed: number | null }> } {
  checkBinary(y, p);
  const out = Array.from({ length: bins }, (_, i) => ({ lo: i / bins, hi: (i + 1) / bins, n: 0, sp: 0, so: 0 }));
  p.forEach((v, i) => { const b = Math.min(bins - 1, Math.floor(v * bins)); out[b].n++; out[b].sp += v; out[b].so += y[i]; });
  const ece = out.reduce((a, b) => a + (b.n ? (b.n / y.length) * Math.abs(b.sp / b.n - b.so / b.n) : 0), 0);
  return { ece, bins: out.map((b) => ({ lo: b.lo, hi: b.hi, n: b.n, meanPred: b.n ? b.sp / b.n : null, observed: b.n ? b.so / b.n : null })) };
}

// ── direct standardisation ───────────────────────────────────────────────────

/** Chi-square quantile by bracketing + bisection on the regularised incomplete gamma (monotone, no randomness). */
export function chi2Quantile(p: number, df: number): number {
  if (!(p > 0 && p < 1) || !(df > 0)) throw new RangeError('p must be in (0,1) and df > 0');
  const cdf = (x: number) => 1 - gammaQ(df / 2, x / 2);
  let lo = 0, hi = Math.max(1, df);
  while (cdf(hi) < p) { hi *= 2; if (hi > 1e12) throw new RangeError('chi2Quantile did not bracket'); }
  for (let i = 0; i < 200; i++) { const mid = (lo + hi) / 2; if (cdf(mid) < p) lo = mid; else hi = mid; if (hi - lo <= 1e-14 * Math.max(1, hi)) break; }
  return (lo + hi) / 2;
}

export interface Stratum { events: number; personTime: number; weight: number }
export interface StandardisedRate { status: 'ok' | 'stratum_without_person_time' | 'invalid'; rate?: number; variance?: number; low?: number; high?: number; crudeRate?: number; confidence: number; note?: string }

/**
 * Directly age/sex-standardised rate: Σ w_i·(d_i/n_i) / Σ w_i, with the Fay–Feuer gamma confidence interval
 * (Fay & Feuer 1997, Stat Med 16:791) — the method used by SEER/NCI. Strata with no person-time make the
 * standardised rate NOT estimable (they are never treated as zero-rate strata).
 */
export function standardisedRate(strata: Stratum[], confidence = 0.95): StandardisedRate {
  if (!strata.length) return { status: 'invalid', confidence, note: 'no strata' };
  for (const s of strata) {
    if (!Number.isInteger(s.events) || s.events < 0 || !Number.isFinite(s.personTime) || s.personTime < 0 || !Number.isFinite(s.weight) || s.weight <= 0) throw new RangeError('invalid stratum');
  }
  if (strata.some((s) => s.personTime === 0)) return { status: 'stratum_without_person_time', confidence, note: 'At least one standard stratum has no person-time in this group; the standardised rate is not estimable (it is not treated as zero).' };
  const W = strata.reduce((a, s) => a + s.weight, 0);
  const w = strata.map((s) => s.weight / W);
  const rate = strata.reduce((a, s, i) => a + w[i] * (s.events / s.personTime), 0);
  const variance = strata.reduce((a, s, i) => a + (w[i] * w[i] * s.events) / (s.personTime * s.personTime), 0);
  const wMax = Math.max(...strata.map((s, i) => w[i] / s.personTime));
  const a2 = (1 - confidence) / 2;
  const low = rate === 0 ? 0 : (variance / (2 * rate)) * chi2Quantile(a2, (2 * rate * rate) / variance);
  const up = rate + wMax, vu = variance + wMax * wMax;
  const high = (vu / (2 * up)) * chi2Quantile(1 - a2, (2 * up * up) / vu);
  const E = strata.reduce((a, s) => a + s.events, 0), T = strata.reduce((a, s) => a + s.personTime, 0);
  return { status: 'ok', rate, variance, low, high, crudeRate: E / T, confidence };
}

/** Ratio of two standardised rates; CI by the delta method on the log scale (an approximation, labelled as such). */
export function standardisedRateRatio(a: StandardisedRate, b: StandardisedRate, confidence = 0.95): RatioResult {
  if (a.status !== 'ok' || b.status !== 'ok') return { status: 'undefined_zero_cell', note: 'A standardised rate is not estimable.' };
  if (!a.rate || !b.rate) return { status: 'undefined_zero_cell', note: 'A standardised rate is zero; the ratio is not estimable without an explicit method.' };
  const ratio = a.rate / b.rate, se = Math.sqrt(a.variance! / (a.rate * a.rate) + b.variance! / (b.rate * b.rate)), z = normQuantile(1 - (1 - confidence) / 2);
  return { status: 'ok', ratio, low: Math.exp(Math.log(ratio) - z * se), high: Math.exp(Math.log(ratio) + z * se), note: 'Delta-method interval on the log scale (approximate).' };
}
